WITH PARAMS AS ( SELECT CASE WHEN LEFT(TRIM(COALESCE(:VAR_DATA_INICIO, '')), 10) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(LEFT(TRIM(:VAR_DATA_INICIO), 10), '%d/%m/%Y') WHEN LEFT(TRIM(COALESCE(:VAR_DATA_INICIO, '')), 10) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN DATE(LEFT(TRIM(:VAR_DATA_INICIO), 10)) ELSE NULL END AS DT_INI_IN, CASE WHEN LEFT(TRIM(COALESCE(:VAR_DATA_FIM, '')), 10) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(LEFT(TRIM(:VAR_DATA_FIM), 10), '%d/%m/%Y') WHEN LEFT(TRIM(COALESCE(:VAR_DATA_FIM, '')), 10) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN DATE(LEFT(TRIM(:VAR_DATA_FIM), 10)) ELSE NULL END AS DT_FIM_IN ), D AS ( SELECT LEAST(DT_INI, DT_FIM) AS DT_INI, GREATEST(DT_INI, DT_FIM) AS DT_FIM, YEAR(GREATEST(DT_INI, DT_FIM)) AS ANO_ATU, YEAR(GREATEST(DT_INI, DT_FIM)) - 1 AS ANO_ANT, DATE_SUB(LEAST(DT_INI, DT_FIM), INTERVAL 1 YEAR) AS DT_INI_ANT, DATE_SUB(GREATEST(DT_INI, DT_FIM), INTERVAL 1 YEAR) AS DT_FIM_ANT FROM ( SELECT COALESCE(DT_FIM_IN, CURDATE()) AS DT_FIM, COALESCE(DT_INI_IN, MAKEDATE(YEAR(COALESCE(DT_FIM_IN, CURDATE())), 1)) AS DT_INI FROM PARAMS ) X ) SELECT NTE_DET.ID AS ID_NOTAS_EXPLICATIVAS_DET, NTE_IMG.URL_IMAGEM FROM NOTAS_EXPLICATIVAS_CAB NTE INNER JOIN NOTAS_EXPLICATIVAS_DET NTE_DET ON NTE.ID = NTE_DET.ID_NOTAS_EXPLICATIVAS_CAB INNER JOIN NOTAS_EXPLICATIVAS_IMAGENS NTE_IMG ON NTE_DET.ID = NTE_IMG.ID_NOTAS_EXPLICATIVAS_DET WHERE NTE.CODEMP = :VAR_EMPRESA_DRE AND DATE(NTE.REFERENCIA) <= (SELECT DT_FIM FROM D) ORDER BY NTE_IMG.DT_CRIACAO;